SELECT c.nu_identif, c.nm_cras, c.logradouro, c.nm_mun
FROM public.cras c
WHERE ST_DWithin(c.geometry::geography, ST_SetSRID(ST_MakePoint(-47.9, -15.8), 4674)::geography, 5000);

SELECT ST_Intersection(p.geometry, ST_Buffer(ST_SetSRID(ST_MakePoint(-43.2, -22.9), 4326)::geography, 100000)::geometry) AS area_intersecao
FROM public.pais p
WHERE p.pais = 'Brasil';

SELECT r.nm_regia, ST_Distance(ST_Centroid(p.geometry)::geography, ST_Centroid(r.geometry)::geography) AS distancia_metros
FROM public.pais p, public.regiao r
WHERE p.pais = 'Brasil';
